SELECT analytics_order_facts.category, COUNT(DISTINCT analytics_order_facts.order_id) AS order_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2025 AND analytics_order_facts.month = 7 AND analytics_order_facts.region = 'Central' AND analytics_order_facts.channel = 'wholesale' AND analytics_order_facts.customer_segment = 'enterprise' GROUP BY analytics_order_facts.category ORDER BY order_count DESC, analytics_order_facts.category ASC LIMIT 12
